package com.tecsup.controller; import com.tecsup.dto.PedidoRequest; import com.tecsup.model.Pedido; import com.tecsup.repository.PedidoRepository; import com.tecsup.service.PedidoService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/pedidos") public class PedidoController {private final PedidoRepository repo;private final PedidoService service;public PedidoController(PedidoRepository r,PedidoService s){repo=r;service=s;}@PostMapping public ResponseEntity<Map<String,Object>> crear(@Valid @RequestBody PedidoRequest r){Pedido p=new Pedido();p.setClienteId(r.clienteId());p.setProductoId(r.productoId());p.setCantidad(r.cantidad());var saved=service.crear(p);return ResponseEntity.status(HttpStatus.CREATED).body(service.detalle(saved.getId()));}@GetMapping("/{id}") public Map<String,Object> one(@PathVariable Long id){return service.detalle(id);}@GetMapping public List<Pedido> all(){return repo.findAll();}@PatchMapping("/{id}/estado") public Pedido estado(@PathVariable Long id,@RequestParam String valor){var p=repo.findById(id).orElseThrow(()->new NoSuchElementException("Pedido no encontrado"));if(!List.of("PENDIENTE","ATENDIDO","ANULADO").contains(valor.toUpperCase()))throw new IllegalArgumentException("Estado invalido");p.setEstado(valor.toUpperCase());return repo.save(p);}}
